import { scopeKey } from '@asam-ui/pro/application/security';
export function adminView(host) {
	const decision = host.security.check(host.pageRule);
	const state = host.security.state.value;
	if (decision === 'pending') return { status: 'pending', entries: [], records: [] };
	if (decision !== 'allowed' || !state.subject)
		return { status: 'denied', entries: [], records: [] };
	const value = host.projection.value;
	if (!value || value.owner !== scopeKey(state.subject) || value.epoch !== state.epoch)
		return { status: 'unavailable', entries: [], records: [] };
	return {
		status: 'ready',
		entries: value.entries.filter((item) => host.security.check(item.rule) === 'allowed'),
		records: value.records.filter((item) => host.security.check(item.rule) === 'allowed')
	};
}
export function adminTarget(host, id) {
	const view = adminView(host);
	return view.status === 'ready'
		? (view.entries.find((item) => item.id === id)?.path ?? null)
		: null;
}

import { computed, shallowRef, watch } from 'vue';
import { createMemoryHistory, createRouter } from 'vue-router';
import {
	createSecurity,
	createSecurityNavigation,
	scopeKey
} from '@asam-ui/pro/application/security';
import { adminTarget, adminView } from './Access.js';
import AdminPage from './AdminPage.vue';
export const adminIdentities = ['admin', 'auditor', 'viewer', 'readonly'];
const home = '/admin/sub-page';
const pageRule = { role: 'admin' };
const entries = [
	{
		id: 'members',
		path: '/admin/members',
		title: 'members',
		description: 'membersHint',
		rule: { role: 'admin', permission: 'members:read' }
	},
	{
		id: 'organization',
		path: '/admin/organization',
		title: 'organization',
		description: 'organizationHint',
		rule: { role: 'admin', permission: 'organization:read' }
	},
	{
		id: 'audit',
		path: '/admin/audit',
		title: 'audit',
		description: 'auditHint',
		rule: { role: 'admin', permission: 'audit:read' }
	}
];
const records = [
	{
		id: 'role',
		event: 'event1',
		owner: 'person1',
		date: '2026-10-30 14:20',
		rule: entries[0].rule
	},
	{
		id: 'member',
		event: 'event2',
		owner: 'person2',
		date: '2026-10-30 11:06',
		rule: entries[0].rule
	},
	{
		id: 'config',
		event: 'event3',
		owner: 'person1',
		date: '2026-10-29 16:42',
		rule: entries[1].rule
	}
];
/** Synthetic subject provider only: no credentials, persistent storage or remote API. */
export function createAdminFixture(i18n) {
	const identity = shallowRef('admin');
	const scope = { tenant: 0, organization: null };
	const contexts = [
		{ ...scope, label: '总部' },
		{ tenant: '0', organization: null, label: '独立工作空间' }
	];
	function subject(currentScope = scope) {
		const value = identity.value;
		return {
			id: value,
			name: value,
			roles: value === 'viewer' ? ['member'] : ['admin'],
			permissions:
				value === 'auditor'
					? ['audit:read']
					: value === 'viewer'
						? []
						: entries.map((item) => item.rule.permission),
			scope: currentScope,
			contexts,
			expiresAt: Date.now() + 300000,
			readOnly: value === 'readonly'
		};
	}
	async function wait() {
		await new Promise((resolve) => setTimeout(resolve, 80));
	}
	const adapter = {
		async login(value) {
			identity.value = value;
			await wait();
			return subject();
		},
		async restore() {
			await wait();
			return subject();
		},
		async refresh(current) {
			await wait();
			return subject(current.scope);
		},
		async switchContext(_current, nextScope) {
			await wait();
			return subject(nextScope);
		},
		async logout() {
			await wait();
		}
	};
	const security = createSecurity({ adapter, i18n });
	const projection = shallowRef(null);
	const stop = watch(
		security.state,
		(state) => {
			projection.value =
				state.status === 'authenticated' && state.subject
					? { owner: scopeKey(state.subject), epoch: state.epoch, entries, records }
					: null;
		},
		{ flush: 'sync', immediate: true }
	);
	const host = { security, pageRule, projection };
	const router = createRouter({
		history: createMemoryHistory(),
		routes: [
			{ path: '/', component: AdminPage },
			{ path: '/safe', component: AdminPage }
		]
	});
	const bridge = createSecurityNavigation({
		security,
		router,
		components: { adminPage: AdminPage },
		items: [
			{ id: 'admin-home', path: home, title: '管理员首页', resource: 'adminPage' },
			...entries.map((item) => ({
				id: item.id,
				path: item.path,
				title: item.title,
				resource: 'adminPage'
			}))
		],
		rules: Object.fromEntries([
			[home, pageRule],
			...entries.map((item) => [item.path, item.rule])
		]),
		publicPaths: ['/', '/safe'],
		safePage: '/safe',
		i18n
	});
	const navigationError = shallowRef(false);
	let intent = 0;
	let disposed = false;
	const stopInvalidate = security.onInvalidate(() => {
		intent++;
		navigationError.value = false;
	});
	async function navigate(path) {
		const token = ++intent;
		navigationError.value = false;
		if (disposed || adminView(host).status !== 'ready') return false;
		try {
			const result = await bridge.navigation.value?.navigate(path);
			if (!disposed && token === intent) navigationError.value = !result;
			return !!result;
		} catch {
			if (!disposed && token === intent) navigationError.value = true;
			return false;
		}
	}
	async function select(value) {
		navigationError.value = false;
		await security.login(value);
	}
	return {
		security,
		host,
		router,
		identity,
		navigationError,
		ready: computed(() => adminView(host).status === 'ready'),
		async initialize() {
			await router.replace(home);
			await security.login('admin');
			await router.isReady();
		},
		select,
		enter(id) {
			const target = adminTarget(host, id);
			return target ? navigate(target) : Promise.resolve(false);
		},
		home() {
			return navigate(home);
		},
		direct() {
			return router.push('/admin/members');
		},
		revoke() {
			return select('viewer');
		},
		switchContext() {
			const current = security.state.value.subject;
			return current
				? security.switchContext(contexts[typeof current.scope.tenant === 'number' ? 1 : 0])
				: Promise.resolve(false);
		},
		dispose() {
			if (disposed) return;
			disposed = true;
			intent++;
			stopInvalidate();
			bridge.dispose();
			stop();
			projection.value = null;
			security.dispose();
		}
	};
}

import { createApp, shallowRef } from 'vue';
import { provideAsamData } from '@asam-ui/ui';
import { AsamI18nKey, createAsamI18n } from '@asam-ui/ui/i18n';
import App from './App.vue';
import { createAdminFixture } from './Fixture.js';
export async function mountAdminAccess(element, host, onError) {
	const locale = shallowRef('zh-CN');
	const i18n = host?.i18n ?? createAsamI18n(() => ({ locale: locale.value }));
	const fixture = createAdminFixture(i18n);
	const app = createApp(App, {
		fixture,
		externalI18n: host?.i18n,
		inheritAppearance: host?.inheritAppearance,
		onLocale: (value) => {
			locale.value = value;
		}
	});
	app.provide(AsamI18nKey, i18n);
	provideAsamData(app, {}, { scope: 'admin-access-demo' });
	app.use(fixture.router);
	if (onError) app.config.errorHandler = onError;
	try {
		await fixture.initialize();
		app.mount(element);
	} catch (error) {
		fixture.dispose();
		if (!host?.i18n) i18n.dispose();
		throw error;
	}
	let disposed = false;
	return () => {
		if (disposed) return;
		disposed = true;
		app.unmount();
		fixture.dispose();
		if (!host?.i18n) i18n.dispose();
	};
}

import { mountAdminAccess } from '../templates/security/admin/mount.js';
export async function mountWebsiteExample(element, onError, i18n) {
	const result = await mountAdminAccess(element, { i18n, inheritAppearance: true }, onError);
	return result;
}
